<?php
require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/helpers.php'; require_role(['Supervisor','HR Admin','Admin']);$pdo=db();$u=current_user();$department=null;if(!empty($u['employee_id'])){$st=$pdo->prepare('SELECT department FROM employees WHERE id=?');$st->execute([$u['employee_id']]);$department=$st->fetchColumn()?:null;}$q=trim((string)($_GET['q']??''));$sql='SELECT employee_code,full_name,department,position,branch,phone,status FROM employees WHERE 1=1';$args=[];if($department && $u['role']==='Supervisor'){$sql.=' AND department=?';$args[]=$department;}if($q!==''){$sql.=' AND (full_name LIKE ? OR employee_code LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}$sql.=' ORDER BY full_name';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$title='Subordinates';require __DIR__.'/../includes/header.php';?>
<div class="page-head"><div><h2>Subordinates</h2><p>Employee directory for supervisory review.</p></div></div><?php if(!$department && $u['role']==='Supervisor'):?><div class="card"><p>Your login is not linked to an employee record, so the list shows all employees. Link the supervisor account to an employee to filter by department.</p></div><?php endif;?><div class="card"><form class="toolbar"><input name="q" value="<?=e($q)?>" placeholder="Search employee name or ID"><button>Search</button></form><div class="table-wrap"><table><tr><th>Employee ID</th><th>Name</th><th>Department</th><th>Position</th><th>Branch</th><th>Phone</th><th>Status</th></tr><?php if(!$rows):?><tr><td colspan="7">No employees found.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['employee_code'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['department'])?></td><td><?=e($r['position'])?></td><td><?=e($r['branch'])?></td><td><?=e($r['phone']??'')?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>